package com.mearvk.sleela.synchro;
import java.net.*;import java.util.Map;
public final class SynchroIntegrationTest{public static void main(String[]a)throws Exception{SynchroStats x=new SynchroStats("local",2);x.record(1.0);x.record(3.0);x.record(5.0);x.record(null);if(x.samples()!=2||x.sent()!=4||x.acked()!=3||x.lost()!=1)throw new AssertionError("statistics mismatch");if(x.percentile(50)!=3.0||x.samplesWithin(3)!=1)throw new AssertionError("percentile/SLA mismatch");DatagramSocket socket=new DatagramSocket(0);int port=socket.getLocalPort();Thread echo=new Thread(()->{try(DatagramSocket s=socket){byte[]b=new byte[256];DatagramPacket p=new DatagramPacket(b,b.length);s.receive(p);s.send(new DatagramPacket(p.getData(),p.getLength(),p.getSocketAddress()));}catch(Exception e){throw new RuntimeException(e);}});echo.start();SynchroIntegration n=new SynchroIntegration(new InetSocketAddress[]{new InetSocketAddress("127.0.0.1",port)},16,500,8);Map<String,SynchroStats>r=n.probe(1,0);echo.join(1000);SynchroStats s=r.get("127.0.0.1:"+port);if(s==null||s.sent()!=1||s.acked()!=1||s.lost()!=0)throw new AssertionError("UDP loopback mismatch");System.out.println("synchro Java integration suite: PASS");}}